import{_ as e,o as i,c as a,a3 as s}from"./chunks/framework.FagJqzbK.js";const p=JSON.parse('{"title":"Performance","description":"","frontmatter":{"order":20,"sidebarTitle":"Performance"},"headers":[],"relativePath":"reference/benchmarks.md","filePath":"reference/benchmarks.md"}'),r={name:"reference/benchmarks.md"};function n(d,t,h,l,g,o){return i(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h1><p>What Hindsight adds to a <code>SaveChanges</code>, measured with BenchmarkDotNet (<code>benchmarks/Hindsight.Benchmarks</code>). One PostgreSQL 17 container serves the whole run; every case uses its own database and measures one <code>SaveChanges</code> per iteration, re-seeding between iterations. <code>None</code> is plain EF Core without Hindsight, the baseline.</p><p>Measured on an AMD Ryzen 7 7800X3D, Windows 11, .NET SDK 10.0.400, PostgreSQL 17 in Docker. <strong>Your numbers will differ</strong>: compare the columns with each other, not with your hardware. To re-run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmarks/Hindsight.Benchmarks</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*&#39;</span></span></code></pre></div><h2 id="insert-update-delete" tabindex="-1">Insert, update, delete <a class="header-anchor" href="#insert-update-delete" aria-label="Permalink to &quot;Insert, update, delete&quot;">​</a></h2><p>Mean time of one <code>SaveChanges</code> over N temporal entities:</p><table tabindex="0"><thead><tr><th>operation</th><th style="text-align:right;">rows</th><th style="text-align:right;">None</th><th style="text-align:right;">Interceptor</th><th style="text-align:right;">Trigger</th></tr></thead><tbody><tr><td>insert</td><td style="text-align:right;">1</td><td style="text-align:right;">1.0 ms</td><td style="text-align:right;">3.4 ms</td><td style="text-align:right;">1.8 ms</td></tr><tr><td>insert</td><td style="text-align:right;">100</td><td style="text-align:right;">9.3 ms</td><td style="text-align:right;">16 ms</td><td style="text-align:right;">12 ms</td></tr><tr><td>insert</td><td style="text-align:right;">1000</td><td style="text-align:right;">63 ms</td><td style="text-align:right;">106 ms</td><td style="text-align:right;">83 ms</td></tr><tr><td>update</td><td style="text-align:right;">1</td><td style="text-align:right;">0.7 ms</td><td style="text-align:right;">3.1 ms</td><td style="text-align:right;">1.0 ms</td></tr><tr><td>update</td><td style="text-align:right;">100</td><td style="text-align:right;">7.5 ms</td><td style="text-align:right;">23 ms</td><td style="text-align:right;">13 ms</td></tr><tr><td>delete</td><td style="text-align:right;">1</td><td style="text-align:right;">0.7 ms</td><td style="text-align:right;">3.0 ms</td><td style="text-align:right;">1.0 ms</td></tr><tr><td>delete</td><td style="text-align:right;">100</td><td style="text-align:right;">6.0 ms</td><td style="text-align:right;">22 ms</td><td style="text-align:right;">12 ms</td></tr></tbody></table><p>Managed allocations for the same calls:</p><table tabindex="0"><thead><tr><th>operation</th><th style="text-align:right;">rows</th><th style="text-align:right;">None</th><th style="text-align:right;">Interceptor</th><th style="text-align:right;">Trigger</th></tr></thead><tbody><tr><td>insert</td><td style="text-align:right;">100</td><td style="text-align:right;">855 KB</td><td style="text-align:right;">1580 KB</td><td style="text-align:right;">960 KB</td></tr><tr><td>insert</td><td style="text-align:right;">1000</td><td style="text-align:right;">8166 KB</td><td style="text-align:right;">14930 KB</td><td style="text-align:right;">9213 KB</td></tr><tr><td>update</td><td style="text-align:right;">100</td><td style="text-align:right;">499 KB</td><td style="text-align:right;">1367 KB</td><td style="text-align:right;">592 KB</td></tr><tr><td>delete</td><td style="text-align:right;">100</td><td style="text-align:right;">373 KB</td><td style="text-align:right;">1228 KB</td><td style="text-align:right;">478 KB</td></tr></tbody></table><ul><li><strong>Trigger</strong> stays within about 1.2–2× plain EF Core. The database writes history inside the same statement; the application pays only for the change-context push, if any, and the transaction around it.</li><li><strong>Interceptor</strong> sends all history statements of a <code>SaveChanges</code> in one batched round trip, split every 512 rows. What remains is executing them: about 1.8× the baseline for a 100-row insert, about 3× for a 100-row update or delete (two statements per row), and about 1.7× at 1000 rows.</li><li>Single-row figures sit close to the round-trip noise floor; read the 100- and 1000-row rows for the trend.</li></ul><h2 id="change-context" tabindex="-1">Change context <a class="header-anchor" href="#change-context" aria-label="Permalink to &quot;Change context&quot;">​</a></h2><p>The same 100-row update, with and without an <code>IChangeContextProvider</code> (a fixed provider with no I/O, so this is the plumbing only):</p><table tabindex="0"><thead><tr><th>writer</th><th style="text-align:right;">without</th><th style="text-align:right;">with</th><th style="text-align:right;">difference</th></tr></thead><tbody><tr><td>Interceptor</td><td style="text-align:right;">23.0 ms</td><td style="text-align:right;">23.8 ms</td><td style="text-align:right;">within noise</td></tr><tr><td>Trigger</td><td style="text-align:right;">12.7 ms</td><td style="text-align:right;">15.7 ms</td><td style="text-align:right;">+3.0 ms, +24 KB</td></tr></tbody></table><p>For the trigger writer, the difference is the one <code>set_config</code> round trip per <code>SaveChanges</code>. For the interceptor writer, the provider call and the five extra columns fold into the round trip it already makes.</p><h2 id="tracked-but-unchanged-entities" tabindex="-1">Tracked but unchanged entities <a class="header-anchor" href="#tracked-but-unchanged-entities" aria-label="Permalink to &quot;Tracked but unchanged entities&quot;">​</a></h2><p>A context that tracks many entities but changes one of them still pays for change detection over the whole graph. <code>ChangeTrackerOverheadBenchmarks</code> measures one <code>SaveChanges</code> that changes one <code>Policy</code> while <code>TrackedUnchangedCount</code> other policies sit unchanged in the same context. Wall-clock time at this scale is mostly noise, so allocations are the signal:</p><table tabindex="0"><thead><tr><th style="text-align:right;">TrackedUnchangedCount</th><th style="text-align:right;">None</th><th style="text-align:right;">Interceptor</th><th style="text-align:right;">Trigger</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td style="text-align:right;">9.09 KB</td><td style="text-align:right;">26.51 KB</td><td style="text-align:right;">10.61 KB</td></tr><tr><td style="text-align:right;">100</td><td style="text-align:right;">59.88 KB</td><td style="text-align:right;">134.55 KB</td><td style="text-align:right;">115.53 KB</td></tr><tr><td style="text-align:right;">1,000</td><td style="text-align:right;">516.75 KB</td><td style="text-align:right;">1,102.20 KB</td><td style="text-align:right;">1,056.81 KB</td></tr><tr><td style="text-align:right;">10,000</td><td style="text-align:right;">5,085.98 KB</td><td style="text-align:right;">10,805.23 KB</td><td style="text-align:right;">10,478.28 KB</td></tr></tbody></table><p>The remaining overhead, about 2× at 10,000 tracked entities, is one extra change-detection pass that Hindsight runs before the writer, so it can reject a save of a historical snapshot before anything is written. To re-run only this benchmark:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmarks/Hindsight.Benchmarks</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*ChangeTrackerOverheadBenchmarks*&#39;</span></span></code></pre></div>',19)])])}const y=e(r,[["render",n]]);export{p as __pageData,y as default};
